// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId, address disputeCaller) public {
        // Call assertionDisputedCallback to satisfy the entry point requirement
        c.assertionDisputedCallback(assertionId);
        // The general rule: isDisputeAllowed always returns true for any input
        assertTrue(c.isDisputeAllowed(assertionId, disputeCaller) == true);
    }
}

